{"approved_file":"subject.py","baseline_feedback":{"assertions":["AssertionError: -5 != 115","AssertionError: 3 != 13","AssertionError: 20 != 120"],"classification":"OWNED_DEVELOPMENT_FEEDBACK","failing_tests":["test_accumulate","test_duplicate","test_opening"],"unseen_evaluation":false},"case_id":"event-reducer","classification":"OWNED_DEVELOPMENT","customer_execution_authorized":false,"delivery_authorized":false,"description":"Apply credits and debits to an opening balance, once per event ID. Ignore unsupported kinds without marking them seen. Return sorted seen IDs and a new state, leaving caller state/events unchanged. Multiple accepted events accumulate, including repeated calls.","edit_units":[{"bindings":["balance"],"end_line":6,"kind":"statement","line":6},{"bindings":["seen"],"end_line":7,"kind":"statement","line":7},{"bindings":[],"end_line":15,"kind":"statement","line":15},{"bindings":[],"end_line":9,"kind":"condition","line":9},{"bindings":[],"end_line":11,"kind":"condition","line":11},{"bindings":["balance"],"end_line":13,"kind":"statement","line":13},{"bindings":[],"end_line":14,"kind":"statement","line":14}],"editable_lines":[6,7,9,11,13,14,15],"engine":"CODEX_AGENT","independent_evaluation":false,"max_attempts":2,"proposal_protocol":"ast_statement_v1","revision":0,"source":"def signed_delta(event):
    return -event["amount"] if event["kind"] == "debit" else event["amount"]


def apply_events(state, events):
    balance = state["balance"]
    seen = set(state["seen"])
    for event in events:
        if event["id"] in seen:
            continue
        if event["kind"] not in ("credit", "debit"):
            continue
        balance = signed_delta(event)
        seen.add(event["id"])
    return {"balance": balance, "seen": tuple(sorted(seen))}
